$string['credit_desc'] = 'A small line, «Eguahe, by Oksigenia», with a link to oksigenia.com, at the foot of the pages and the emails of the families, of the posters and of the screens of the team, and the seal of Eguahe on what families share (the drawing, the story, the invitation and the events) and at the end of their videos. Off by default.';
