$string['decide_days'] = '{$a} days';
$string['decide_def'] = 'How it is counted: the first contact is the first word of the family or the day it was written down. “Stayed at their first contact”, those that in {$a->days} days did not write again, came to nothing and took no other step, without those that went with a reason; the most recent do not count yet. The days, the median and, of the middle half, the first and the last, only with at least {$a->min} families. “An earlier campaign”, if their first contact was before this one started or they left their contact in an imported campaign. The families already of the centre do not count here.';
