$string['howto_bounced'] = 'Call a family whose mail comes back';
$string['howto_bounced_steps'] = 'In the inbox, “Their mail does not arrive”: the families to call.|In their record, above “How to reach them”: the address, why (it does not exist, the mailbox is full, their server refuses it), what did not arrive, their phones and what to say.|After the call: write the right address and “Save the right address” (what did not arrive of an act still to come goes again), or “No answer”, “They want no email” or “Leave it”.|Eguahe reads the returned mail every 15 minutes; nobody has to look at the mailbox.';
