$string['howto_code'] = 'A family says they got a code';
$string['howto_code_steps'] = 'It is a 6-digit code that reaches the family\'s email, and their Telegram if it is joined, when someone asks from their page to download or erase their data.|It tells us it is them and not someone who got the link. It lasts 15 minutes.|If they did not ask for it, they need do nothing: without the code nothing is downloaded or erased. If they are worried, «Make a new link» in their record stops the old links working.|Their record\'s history shows when it was sent and to which addresses.';
$string['howto_code_words'] = 'code, 6 digits, six digits, security code, code they did not ask for, got a code, code by email, code by telegram, verify, verification, check, download their data, erase their data, one-time password, otp';
