$string['howto_notices_words'] = 'notice sent, reminder sent, resend the reminder, confirmation did not arrive, send the email again, resend the appointment';
$string['howto_pauseinvite'] = 'Stop and resume a letter that is going out';
$string['howto_pauseinvite_steps'] = 'On the page of the act, while the letter goes out (15 every 25 minutes, from 9 to 20), “Stop” holds the rest.|The page says how many are left; “Resume” sends them from where it stopped, at the same pace.|On resuming, those who signed up, already got it or asked for no more are left out.';
$string['howto_pauseinvite_words'] = 'stop the letter, stop the invitation, pause, resume, keep sending, letters queued, batches, how many are left, cancel sending';
$string['howto_phonebatches'] = 'Send the letter by WhatsApp in batches';
$string['howto_phonebatches_steps'] = 'On the page of the act, under “In batches”, pick how many families go in each batch and every how long, and “Start in batches”.|It goes to the families that have the letter by mail and have not answered, spread over the whole list, from 9 to 20; never to whoever already has it by phone.|Each batch says how many it reached, how many read it, how many are coming or not, who answered on WhatsApp and who asked for no more.|It stops by itself if Meta lowers the rating of the number, if several families of a batch ask for no more or if most are not delivered; “Go on” resumes it and “No more batches” ends it.';
$string['howto_phonebatches_words'] = 'whatsapp in batches, letter by whatsapp, invitation by whatsapp, a few at a time, send by whatsapp, meta rating, quality of the number, green number, whatsapp spam, whatsapp opt-outs, telegram in batches';
$string['howto_permitinvite'] = 'Give the email permission when inviting to an act';
$string['howto_permitinvite_steps'] = 'In “Invite”, if some families are left out only because they have no email permission, it says so at the top and in the review before sending.|If they left their contact to be written to (a form, a call, the sheet), “Give them the email permission” gives it and they join the list.|Never to whoever said no, asked not to be written to or chose other ways. Their record says who gave it.';
$string['howto_permitinvite_words'] = 'email permission, no permission, give permission, consent, why the invitation does not reach them, families left out';
$string['howto_samefamily'] = 'Put two records of the same family together, or split them';
$string['howto_samefamily_steps'] = 'When two records may be the same family, the record says so («This may be the same family») and the inbox warns, with why: the same child, the same course or the same phone.|To join them: in the record, «They are the same family». One stays, the oldest, with everything of both.|If they are not: «No, they are different families»; it is not asked again.|To split a record that holds two families: in the record, «Separate into two families», and tick which adults, children and sign-ups go.|If Eguahe does not recognise it: in “Their page and their data”, “Put together with another file…”, by its name, email or phone.';
$string['howto_samefamily_words'] = 'join, merge, duplicate, duplicated, repeated, twice, same family, double record, split, separate, divide, two families, signed up twice, same phone, same child, put together by hand';
$string['howto_applysend'] = 'Send a family how to apply for a place';
$string['howto_applysend_steps'] = 'In the record, «Send them how to apply»: it leaves in the composer the message written with what the school put in Settings, in «How to apply for a place».|Read it, change what is needed and send it. The record then says when it was sent.|Before the application time opens, the message says from which day; once it is over, it is not offered.';
$string['howto_applysend_words'] = 'apply, application, apply for a place, enrolment, enrol, enrollment, admission, deadline, how to apply, send the application, application link, admission form';
$string['howto_alumni'] = 'Note that someone of the family studied at the school';
$string['howto_alumni_steps'] = 'In the record, under each adult: «Note that they studied at the centre».|If a note says someone of the family studied here, the record asks for each adult: «It was this person».|The family can also say it from their page, with the year they finished.|Families of former students have their filter in the inbox, count apart in Numbers and can be invited alone to an open act.';
$string['howto_alumni_words'] = 'former student, alumnus, alumna, alumni, studied here, studied at the school, graduated, graduate, class of, year they finished, parents who studied here';
$string['howto_settled'] = 'Say of several families that came that they are answered';
$string['howto_settled_steps'] = 'In the inbox, under «Also today», open «Perhaps already answered».|Leave as «Answered» those that are, and as «Still waits» those that are not.|Press the button of the group. «Undo» leaves it as it was.';
$string['howto_settled_words'] = 'mark several as answered, already answered, answered at once';
$string['howto_whocame'] = 'Note whether a family kept its appointment';
$string['howto_whocame_steps'] = 'In «Open days and visits», in the week, answer «Yes» or «No» on each appointment that passed.|For several at once, press «Note it»: one by one or the whole day.|Of an open day or an event that is over, on its page: first those that did not come, then «The rest came».|If it was a mistake, «Undo».';
$string['howto_whocame_words'] = 'kept the appointment, no show at the appointment, missed the appointment';
$string['howto_writeby'] = 'Note how they want to be written to: email, WhatsApp or Telegram';
$string['howto_writeby_steps'] = 'In the record, «How we write to them» → «Note how they prefer to be written to»: tick email, WhatsApp or Telegram (those the school has on) and save.|If they want no messages: «No messages wanted».|If they asked not to be written to and they need an answer, the composer is off until «Write anyway».|The family also changes it from their page and from every email.';
