$string['howto_chatfamily'] = 'See the family beside the chat conversation';
$string['howto_chatfamily_steps'] = 'In the school’s chat, the «Family» panel shows who is writing: whether they ask for a place or are of the school, their children with their step, how long they wait and who looks after them.|If nobody knows them, «Note a new family» notes them with the name, phone and email of the chat.|Whoever runs the site turns it on, in «Chats that show the family», with the chat on the same domain as the platform.';
