$string['howto_ties'] = 'Mark that a child is already at the centre or of the house';
$string['howto_ties_steps'] = 'In the file of the family, under the name of the child: “Tie with the centre”.|One touch marks: already in the nursery, already a student, brothers or sisters at the centre, family of the staff, family of former students. Several can be marked.|Another touch takes it out, and the history says who marked it.|The numbers count these families as “already of the centre”, apart from those that come new, even if they come to an open day.';
