$string['panel_bychannel_best'] = 'Among the channels with at least {$a->fair} families, the one that enrols most is {$a->best} ({$a->bestfrac}) and the one that enrols least, {$a->worst} ({$a->worstfrac}).';
$string['panel_bychannel_foot'] = 'How it is counted: the origin is the first measured contact and never changes afterwards. An open day, a call or the poster at the door are doors, never the origin, and an ad only counts if the family was new. The Google profile, by utm_medium=ficha; advertising, by a paid medium (cpc, paid, ads, campaign); the centre’s emails and messages, by email, newsletter or sms; print, by qr or impreso; networks, by social or by coming from a network; the centre’s website, by the domain of its email or by its forms. With nothing measured, what the family said in “How did you hear about us?” counts; if it did not say either, it goes to “Not measured” and is put down to no one. No channel gets more than was measured: an ad seen without a click leaves no trace and may end in a search or a straight visit to the website, and a family that leaves its contact in an ad may have known the centre before. Who they are comes from the centre’s lists, from what families and the team say, and from the list of former students.';
