$string['panel_isthis'] = 'What is this?';
$string['panel_isthis_bridge'] = 'A bridge brings into Eguahe what arrives through another tool (the Google or Meta adverts, the admissions mailbox or a form you already have), so that each family has its card and is answered from the inbox.';
$string['panel_isthis_entries'] = 'An entry is a way families come in: the form on your website, a QR code on a poster, the admissions mailbox or the Google or Meta adverts. Each family that comes in through one counts as an arrival, and here you see which one brings most.';
$string['panel_isthis_forecast'] = 'The forecast works out, from the children in the area and from past campaigns, how many families might ask for a place in each course. It is not a promise: it is a reasonable range to plan places and groups.';
$string['panel_isthis_kit'] = 'The kit is what you share so that families sign up to an event: the link, the QR code for the poster, the posters and the texts for social media and the channel, ready to copy.';
$string['panel_isthis_labels'] = 'Backpack labels carry each child\'s name handwritten, as on their page. They are printed on sticker sheets and handed out at the door of the event.';
$string['panel_isthis_metrics'] = 'Numbers shows how the campaign is going: how many families ask, how many visit and how many enrol, how they come in and how many places are left. Each number says what it counts underneath.';
$string['panel_isthis_renewal'] = 'Here the families already at the school are asked whether their children stay on next school year. They answer on their page with one tap, and you see, course by course, who stays, who does not and who is not sure yet: so you know how many places are left for new pupils.';
$string['panel_isthis_start'] = 'The first day is the day each course starts. Here you mark each child who starts, and with that date Eguahe knows when to give their family the story of their first day and when to ask how it went.';
