$string['panel_voice_channel'] = 'By channel';
$string['panel_voice_channel_def'] = 'Where they really come from: the first measured contact of each family, never the open day or the form it came in by, and with the ones that were lost too. First, the centre’s own channels (its website, search engines, AI assistants, its Google profile, its networks, its emails and messages, and word of mouth); then advertising; then other ways (print and QR, other websites, not through the web); and last what was not measured. Each channel with how far its families went and who they are: the really new, those already of the centre (not counted in the other figures), those that had children there before and those of former students.';
