$string['privacy_rights_self'] = 'From your page you can download your data or erase it whenever you want. You can also ask for access, rectification, restriction or objection, and complain to the data protection authority.';
$string['privacy_rights_title'] = 'Your rights';
$string['privacy_what'] = 'Your name and how to reach you; the name of who would study, what you call them at home and the course. If you say so: where you live, how you heard of the centre, the date of birth, brothers and sisters who would come later, what you like to do in your free time, your children’s drawing, your answers to the centre’s questions and whether your children carry on next year. And what you write to the centre and the channels you allow.';
$string['privacy_what_self'] = 'Your name, how to reach you and what you would like to study. If you say so: where you live, how you heard of the centre, your date of birth, what you like to do in your free time, your answers to the centre\'s questions and whether you carry on next year. And what you write to the centre and the channels you allow.';
$string['privacy_what_title'] = 'Which data';
