$string['privacy_who_dpo'] = 'Its data protection officer: {$a->dpo}.';
$string['privacy_who_title'] = 'Who is responsible';
$string['privacy_whom'] = 'Nobody outside the centre, unless the law requires it. The provider of the platform processes it on behalf of the centre and only for it. The centre never sells it nor puts a mark on any family.';
$string['privacy_whom_ai'] = 'The centre’s artificial intelligence provider receives the text of the messages, without emails, phones or links, to prepare the drafts.';
$string['privacy_whom_messaging'] = 'If you join by WhatsApp or Telegram from your page, the notices go through Meta or Telegram.';
$string['privacy_whom_title'] = 'Who else sees it';
$string['privacy_whom_voices'] = 'So that the first-day story says your child’s name, that name, and nothing else, goes to Oksigenia’s voice service, which records the reading.';
$string['privacy_why'] = 'To answer your questions, organise your visits and open days and, if you wish, your admission. And to know, with numbers that never name anyone, how the campaign is going.';
