$string['qs_letters_def'] = 'The letters of the acts that went by mail in this campaign, without the samples; those that came back do not count in the times nor in the days. A letter is opened when the family opens its link and looks at it for a moment: programs that check links do not count. “Opened within two days” looks only at those out for two days already, so that the recent ones do not seem worse. “Half reacted within” is the time within which half of the families that opened it or answered within a week did, with five or more. The time and the day are those of the centre.';
